import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("NO")
        return

    n = int(data[0])
    if n == 0:
        print("NO")
        return

    arr = data[1:n+1]

    seen = {}
    for i, num in enumerate(arr):
        seen[num] = i

    for i, num in enumerate(arr):
        rev = num[::-1]
        if rev in seen and seen[rev] != i:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    main()
